import { ObjectData } from "../model/graph";
import { RectangleXY } from "../util";
/**
 * Base region used by RTree
 * @internal
 */
export interface RTreeRegion extends RectangleXY {
    data?: ObjectData;
    children: Array<RTreeRegion>;
    parent?: RTreeRegion;
    id?: string;
}
/**
 * Default max child count for RTree nodes
 * @internal
 */
export declare const RTREE_DEFAULT_MAX_CHILD_ENTRIES = 4;
/**
 * A data node in an RTree
 * @internal
 */
export interface RTreeDataNode extends RTreeRegion {
    id: string;
}
